diff --git a/src/kded/jackdeviceselector.cpp b/src/kded/jackdeviceselector.cpp
new file mode 100644
index 00000000..4980021f
--- /dev/null
+++ b/src/kded/jackdeviceselector.cpp
@@ -0,0 +1,214 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "jackdeviceselector.h"
+
+#include <KLocalizedString>
+#include <KNotification>
+
+#include <PulseAudioQt/Card>
+#include <PulseAudioQt/CardPort>
+#include <PulseAudioQt/Context>
+#include <PulseAudioQt/Models>
+#include <PulseAudioQt/Sink>
+#include <PulseAudioQt/Source>
+
+using namespace Qt::StringLiterals;
+
+JackDeviceSelector::JackDeviceSelector(QObject *parent)
+    : QObject(parent)
+    , m_cardModel(new PulseAudioQt::CardModel(this))
+{
+    connect(m_cardModel, &PulseAudioQt::CardModel::rowsInserted, this, [this](const QModelIndex &, int first, int last) {
+        addCards(first, last);
+    });
+    connect(m_cardModel, &PulseAudioQt::CardModel::rowsAboutToBeRemoved, this, [this](const QModelIndex &, int first, int last) {
+        removeCards(first, last);
+    });
+    addCards(0, m_cardModel->rowCount() - 1);
+}
+
+JackDeviceSelector::~JackDeviceSelector()
+{
+    for (const QPointer<KNotification> &notification : std::as_const(m_ambiguousJacks)) {
+        if (notification) {
+            notification->close();
+        }
+    }
+}
+
+void JackDeviceSelector::addCards(int first, int last)
+{
+    for (int i = first; i <= last; ++i) {
+        auto card = m_cardModel->index(i).data(PulseAudioQt::AbstractModel::PulseObjectRole).value<PulseAudioQt::Card *>();
+        if (!card) {
+            continue;
+        }
+        // Jacks that are already plugged in when we start are left alone, only plugging one in asks
+        updateCard(card, false);
+        connect(card, &PulseAudioQt::Card::portsChanged, this, [this, card] {
+            updateCard(card, true);
+        });
+    }
+}
+
+void JackDeviceSelector::removeCards(int first, int last)
+{
+    for (int i = first; i <= last; ++i) {
+        auto card = m_cardModel->index(i).data(PulseAudioQt::AbstractModel::PulseObjectRole).value<PulseAudioQt::Card *>();
+        if (!card) {
+            continue;
+        }
+        disconnect(card, nullptr, this, nullptr);
+        for (auto it = m_ambiguousJacks.begin(); it != m_ambiguousJacks.end();) {
+            if (it.key().first == card->index()) {
+                if (it.value()) {
+                    it.value()->close();
+                }
+                it = m_ambiguousJacks.erase(it);
+            } else {
+                ++it;
+            }
+        }
+    }
+}
+
+void JackDeviceSelector::updateCard(PulseAudioQt::Card *card, bool notify)
+{
+    struct JackState {
+        Jack jack;
+        bool headphonesPlugged = false;
+        bool micUndetected = false;
+    };
+    QHash<QString, JackState> jacks;
+    for (const PulseAudioQt::CardPort *port : card->ports()) {
+        const QString group = port->availabilityGroup();
+        if (group.isEmpty()) {
+            continue;
+        }
+        JackState &state = jacks[group];
+        switch (port->type()) {
+        case PulseAudioQt::Port::Headphones:
+            state.jack.headphonesPort = port->name();
+            state.headphonesPlugged = port->availability() != PulseAudioQt::Profile::Unavailable;
+            break;
+        case PulseAudioQt::Port::Headset:
+            state.jack.headsetMicPort = port->name();
+            state.micUndetected |= port->availability() == PulseAudioQt::Profile::Unknown;
+            break;
+        case PulseAudioQt::Port::Mic:
+            state.jack.micPort = port->name();
+            state.micUndetected |= port->availability() == PulseAudioQt::Profile::Unknown;
+            break;
+        default:
+            break;
+        }
+    }
+
+    // Something is plugged into the jack, but the server can't tell whether it has a microphone
+    for (auto it = jacks.cbegin(); it != jacks.cend(); ++it) {
+        const bool isAmbiguous = it->headphonesPlugged && it->micUndetected;
+        const JackKey key{card->index(), it.key()};
+        if (isAmbiguous && !m_ambiguousJacks.contains(key)) {
+            m_ambiguousJacks.insert(key, nullptr);
+            if (notify) {
+                showNotification(card, key, it->jack);
+            }
+        } else if (!isAmbiguous && m_ambiguousJacks.contains(key)) {
+            if (auto notification = m_ambiguousJacks.take(key)) {
+                notification->close();
+            }
+        }
+    }
+}
+
+void JackDeviceSelector::showNotification(PulseAudioQt::Card *card, const JackKey &key, const Jack &jack)
+{
+    QString cardName = card->properties().value(u"device.description"_s).toString();
+    if (cardName.isEmpty()) {
+        cardName = card->name();
+    }
+
+    auto notification = new KNotification(u"jackPlugged"_s, KNotification::Persistent);
+    notification->setComponentName(u"plasma_pa"_s);
+    notification->setIconName(u"audio-headset"_s);
+    notification->setTitle(i18nc("@title notification", "Audio Device Plugged In"));
+    notification->setText(i18nc("@info %1 is the name of a sound card", "What did you plug into %1?", cardName));
+
+    const quint32 cardIndex = key.first;
+    const QString group = key.second;
+    auto headphones = notification->addAction(i18nc("@action:button", "Headphones"));
+    connect(headphones, &KNotificationAction::activated, this, [this, cardIndex, group, jack] {
+        selectPorts(cardIndex, group, jack.headphonesPort, QString());
+    });
+    if (!jack.headsetMicPort.isEmpty()) {
+        auto headset = notification->addAction(i18nc("@action:button headphones with a microphone", "Headset"));
+        connect(headset, &KNotificationAction::activated, this, [this, cardIndex, group, jack] {
+            selectPorts(cardIndex, group, jack.headphonesPort, jack.headsetMicPort);
+        });
+    }
+    if (!jack.micPort.isEmpty()) {
+        auto microphone = notification->addAction(i18nc("@action:button", "Microphone"));
+        connect(microphone, &KNotificationAction::activated, this, [this, cardIndex, group, jack] {
+            selectPorts(cardIndex, group, QString(), jack.micPort);
+        });
+    }
+
+    m_ambiguousJacks.insert(key, notification);
+    notification->sendEvent();
+}
+
+// An empty port name moves the devices that are using the jack to their best port outside of it
+void JackDeviceSelector::selectPorts(quint32 cardIndex, const QString &group, const QString &outputPort, const QString &inputPort)
+{
+    const QList<PulseAudioQt::Card *> cards = PulseAudioQt::Context::instance()->cards();
+    auto it = std::find_if(cards.cbegin(), cards.cend(), [cardIndex](PulseAudioQt::Card *card) {
+        return card->index() == cardIndex;
+    });
+    if (it == cards.cend()) {
+        return;
+    }
+    for (PulseAudioQt::Sink *sink : (*it)->sinks()) {
+        selectPort(sink, group, outputPort);
+    }
+    for (PulseAudioQt::Source *source : (*it)->sources()) {
+        selectPort(source, group, inputPort);
+    }
+}
+
+void JackDeviceSelector::selectPort(PulseAudioQt::Device *device, const QString &group, const QString &portName)
+{
+    const QList<PulseAudioQt::Port *> ports = device->ports();
+    qsizetype choice = -1;
+    if (!portName.isEmpty()) {
+        for (qsizetype i = 0; i < ports.size(); ++i) {
+            if (ports.at(i)->name() == portName) {
+                choice = i;
+                break;
+            }
+        }
+        if (choice >= 0) {
+            device->setActivePortIndex(choice);
+            device->setDefault(true);
+        }
+        return;
+    }
+
+    const qsizetype active = device->activePortIndex();
+    if (active < 0 || active >= ports.size() || ports.at(active)->availabilityGroup() != group) {
+        return;
+    }
+    for (qsizetype i = 0; i < ports.size(); ++i) {
+        const PulseAudioQt::Port *port = ports.at(i);
+        if (port->availabilityGroup() != group && (choice < 0 || port->priority() > ports.at(choice)->priority())) {
+            choice = i;
+        }
+    }
+    if (choice >= 0) {
+        device->setActivePortIndex(choice);
+    }
+}
+
+#include "moc_jackdeviceselector.cpp"
diff --git a/src/kded/jackdeviceselector.h b/src/kded/jackdeviceselector.h
new file mode 100644
index 00000000..8927283e
--- /dev/null
+++ b/src/kded/jackdeviceselector.h
@@ -0,0 +1,48 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QHash>
+#include <QObject>
+#include <QPointer>
+
+class KNotification;
+
+namespace PulseAudioQt
+{
+class Card;
+class CardModel;
+class Device;
+} // namespace PulseAudioQt
+
+// Asks what was plugged into a jack when the sound server can't tell
+// headphones, headsets and microphones apart (ports sharing an availability group)
+class JackDeviceSelector : public QObject
+{
+    Q_OBJECT
+
+public:
+    explicit JackDeviceSelector(QObject *parent = nullptr);
+    ~JackDeviceSelector() override;
+
+private:
+    struct Jack {
+        QString headphonesPort;
+        QString headsetMicPort;
+        QString micPort;
+    };
+    using JackKey = std::pair<quint32, QString>;
+
+    void addCards(int first, int last);
+    void removeCards(int first, int last);
+    void updateCard(PulseAudioQt::Card *card, bool notify);
+    void showNotification(PulseAudioQt::Card *card, const JackKey &key, const Jack &jack);
+    void selectPorts(quint32 cardIndex, const QString &group, const QString &outputPort, const QString &inputPort);
+    static void selectPort(PulseAudioQt::Device *device, const QString &group, const QString &portName);
+
+    PulseAudioQt::CardModel *m_cardModel = nullptr;
+    QHash<JackKey, QPointer<KNotification>> m_ambiguousJacks;
+};
diff --git a/src/kded/plasma_pa.notifyrc b/src/kded/plasma_pa.notifyrc
new file mode 100644
index 00000000..3779fff6
--- /dev/null
+++ b/src/kded/plasma_pa.notifyrc
@@ -0,0 +1,8 @@
