From 661d97bbfff43c142f535cbd83f1b1e1040dc1fd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:01:11 +0100
Subject: [PATCH] Port: add availabilityGroup

Ports behind the same jack share an availability group: the server uses
it to say that it can't tell whether headphones, a headset or a mic was
plugged in. Expose it so that clients can ask the user which one it was.

CCBUG: 424273
---
 src/port.cpp |  5 +++++
 src/port.h   | 12 ++++++++++++
 src/port_p.h |  6 ++++++
 3 files changed, 23 insertions(+)

diff --git a/src/port.cpp b/src/port.cpp
index 0fff169..d8fcf4a 100644
--- a/src/port.cpp
+++ b/src/port.cpp
@@ -32,4 +32,9 @@ Port::Type Port::type() const
     return d->m_type;
 }

+QString Port::availabilityGroup() const
+{
+    return d->m_availabilityGroup;
+}
+
 } // PulseAudioQt
diff --git a/src/port.h b/src/port.h
index d6bdd99..3604652 100644
--- a/src/port.h
+++ b/src/port.h
@@ -19,6 +19,7 @@ class PULSEAUDIOQT_EXPORT Port : public Profile
 {
     Q_OBJECT
     Q_PROPERTY(Type type READ type NOTIFY typeChanged)
+    Q_PROPERTY(QString availabilityGroup READ availabilityGroup NOTIFY availabilityGroupChanged)

 public:
     ~Port() override;
@@ -52,8 +53,19 @@ public:

     Type type() const;

+    /**
+     * Ports that share a non-empty availability group are behind the same jack, and
+     * the server can't tell which of them is really connected when it is plugged in.
+     * @since 1.10
+     */
+    QString availabilityGroup() const;
+
 Q_SIGNALS:
     void typeChanged();
+    /**
+     * @since 1.10
+     */
+    void availabilityGroupChanged();

 protected:
     /** @private */
diff --git a/src/port_p.h b/src/port_p.h
index 7501c66..c61a44b 100644
--- a/src/port_p.h
+++ b/src/port_p.h
@@ -20,6 +20,7 @@ public:

     Port *q;
     Port::Type m_type = Port::Type::Unknown;
+    QString m_availabilityGroup;

     template<typename PAInfo>
     void setInfo(const PAInfo *info)
@@ -38,6 +39,11 @@ public:

 #if PA_CHECK_VERSION(14, 0, 0)
         m_type = static_cast<Port::Type>(info->type);
+        const QString availabilityGroup = QString::fromUtf8(info->availability_group);
+        if (m_availabilityGroup != availabilityGroup) {
+            m_availabilityGroup = availabilityGroup;
+            Q_EMIT q->availabilityGroupChanged();
+        }
 #endif
         Q_EMIT q->typeChanged();

